// Conversion offer logic: when paidEvents is zero, inject a discount offer into checkout
module.exports = function conversionOffer(req, res, next) {
  if (req.path === '/checkout' && req.method === 'GET') {
    // Inject a 10% discount offer banner
    req.offer = { type: 'discount', value: 0.1, message: 'Use code UNICORN10 for 10% off!' };
  }
  next();
};
